    F(["Champagne millesimato: uscita minima", "Champagne millésimé : sortie minimale", "Vintage Champagne: earliest release", "Champagne de añada: salida mínima"], ["Tre anni dal tiraggio (12 mesi almeno sui lieviti)", "Trois ans après tirage (12 mois au moins sur lies)", "Three years from tirage (at least 12 months on lees)", "Tres años desde el tiraje (al menos 12 meses sobre lías)"]),
    F(["Taille Chablis", "Taille Chablis", "Taille Chablis", "Taille Chablis"], ["Potatura a cordone con molto legno vecchio, tipica dello Chardonnay", "Taille en cordon avec beaucoup de vieux bois, typique du Chardonnay", "Cordon pruning with plenty of old wood, typical for Chardonnay", "Poda en cordón con mucha madera vieja, típica de la Chardonnay"]),
    F(["NM · RM · CM", "NM · RM · CM", "NM · RM · CM", "NM · RM · CM"], ["Casa che compra uve · vigneron · cooperativa", "Maison qui achète du raisin · vigneron · coopérative", "House buying grapes · grower · co-operative", "Casa que compra uva · viticultor · cooperativa"]),
    F(["Villaggi grand cru e premier cru", "Villages grands crus et premiers crus", "Grand cru and premier cru villages", "Pueblos grand cru y premier cru"], ["17 grand cru, 42 premier cru", "17 grands crus, 42 premiers crus", "17 grand cru, 42 premier cru", "17 grand cru, 42 premier cru"]),
    F(["Rosé de saignée", "Rosé de saignée", "Rosé de saignée", "Rosé de saignée"], ["Rosé da breve macerazione delle uve nere, non da assemblaggio", "Rosé issu d'une courte macération de raisins noirs, non d'assemblage", "Rosé from short maceration of black grapes, not from blending", "Rosado por maceración corta de uvas tintas, no por ensamblaje"]),
    F(["Costi di una bottiglia di Champagne", "Coûts d'une bouteille de champagne", "Costs of a bottle of Champagne", "Costes de una botella de champagne"], ["Uva 50%, produzione 30%, commercializzazione 20%", "Raisin 50 %, élaboration 30 %, commercialisation 20 %", "Grapes 50%, production 30%, commercialisation 20%", "Uva 50 %, elaboración 30 %, comercialización 20 %"])
